-- =============================================================================
-- 541 — LE CAHIER D'EXERCICES DE 1RE (partie 29)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/1re/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 541 --niveau 1re --fichiers nsi.n1,nsi.n2,physique-chimie-maths.n1 --suffixe 29 > supabase/contenu/541_exercices_1re_29.sql
--
-- 81 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   nsi.n1                  30 exercices · 10 chapitres
--   nsi.n2                  27 exercices · 9 chapitres
--   physique-chimie-maths.n1  24 exercices · 8 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('53b26f6c-f960-5e34-adc7-f3714b4fff47'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Les quatre voyants de la serrure","competence":"calculer","situation":"Jade ouvre le coffre de son club d’informatique : la serrure affiche un nombre avec quatre voyants. Un voyant allumé vaut 1, un voyant éteint vaut 0, et chaque voyant a un poids.","documents":[{"id":"voyants","type":"tableau","titre":"L’afficheur de la serrure","colonnes":["Voyant","Poids 8","Poids 4","Poids 2","Poids 1"],"lignes":[["État (1 = allumé)",1,0,1,1]],"enteteLignes":false,"source":"Afficheur imaginé pour l’exercice"}],"questions":[{"enonce":"Touche le voyant allumé qui a le plus grand poids.","aide":"Les poids décroissent de gauche à droite : cherche le premier 1 en partant de la gauche.","type":"zone","document":"voyants","multiple":false},{"enonce":"Quel nombre décimal la serrure affiche-t-elle ?","aide":"Additionne les poids des seuls voyants allumés.","type":"nombre"},{"enonce":"Pour afficher le nombre 6, quelle ligne de voyants (poids 8, 4, 2, 1) faut-il obtenir ?","aide":"Décompose 6 en somme de poids : 6 = 4 + 2.","type":"choix","options":[{"id":"a","texte":"0110"},{"id":"b","texte":"1100"},{"id":"c","texte":"0011"},{"id":"d","texte":"1001"}],"multiple":false},{"enonce":"Combien de nombres différents (0 compris) les quatre voyants peuvent-ils afficher ?","aide":"Chaque voyant a 2 états : multiplie 2 par lui-même quatre fois.","type":"nombre"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c1"]},"explication":"Le voyant de poids **8** est allumé : c’est le bit de poids fort, celui qui pèse le plus."},{"cle":{"type":"nombre","valeur":11,"tolerance":0},"affichage":"11","explication":"Voyants allumés : 8, 2 et 1. 8 + 2 + 1 = **11**."},{"cle":{"type":"choix","ids":["a"]},"explication":"6 = 4 + 2 : seuls les voyants de poids 4 et 2 sont allumés, soit **0110**."},{"cle":{"type":"nombre","valeur":16,"tolerance":0},"affichage":"16","explication":"Avec n bits on code 2ⁿ valeurs : 2⁴ = **16** nombres, de 0 à 15."}]$ex$::jsonb),
  ('53b26f6c-f960-5e34-adc7-f3714b4fff47'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Le numéro du casier","competence":"calculer","situation":"Le casier numéro 45 doit être affiché sur un panneau à voyants. Anaïs convertit 45 en binaire par divisions successives par 2 et note ses calculs ; trois cases restent à compléter.","documents":[{"id":"div","type":"tableau","titre":"Les divisions d’Anaïs","colonnes":["Opération","Quotient","Reste"],"lignes":[["45 ÷ 2",22,1],["22 ÷ 2",11,"?"],["11 ÷ 2",5,1],["5 ÷ 2","?",1],["2 ÷ 2",1,0],["1 ÷ 2",0,"?"]],"enteteLignes":false,"source":"Calculs écrits pour l’exercice"}],"questions":[{"enonce":"Quel est le reste de la division 22 ÷ 2 ?","aide":"22 est-il pair ou impair ?","type":"nombre"},{"enonce":"Quel est le quotient de la division 5 ÷ 2 ?","aide":"Combien de fois 2 tient-il entièrement dans 5 ?","type":"nombre"},{"enonce":"Touche le reste qui donne le premier chiffre (à gauche) de l’écriture binaire de 45.","aide":"Les restes se lisent de bas en haut.","type":"zone","document":"div","multiple":false},{"enonce":"Quelle est l’écriture binaire de 45 ?","aide":"Lis la colonne des restes de bas en haut : 1, 0, 1, 1, 0, 1.","type":"choix","options":[{"id":"a","texte":"101101"},{"id":"b","texte":"110101"},{"id":"c","texte":"101011"},{"id":"d","texte":"100111"}],"multiple":false},{"enonce":"Combien de chiffres binaires (bits) compte l’écriture de 45 ?","aide":"Une division = un reste = un bit.","type":"nombre"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":0,"tolerance":0},"affichage":"0","explication":"22 = 2 × 11 + 0 : le reste est **0**."},{"cle":{"type":"nombre","valeur":2,"tolerance":0},"affichage":"2","explication":"5 = 2 × 2 + 1 : le quotient est **2**."},{"cle":{"type":"zone","ids":["r5c2"]},"explication":"On lit les restes **de bas en haut** : le dernier reste, celui de 1 ÷ 2, devient le chiffre de gauche."},{"cle":{"type":"choix","ids":["a"]},"explication":"Restes lus de bas en haut : 1, 0, 1, 1, 0, 1, soit **101101**. Vérification : 32 + 8 + 4 + 1 = 45."},{"cle":{"type":"nombre","valeur":6,"tolerance":0},"affichage":"6","explication":"Il y a 6 divisions donc 6 restes : l’écriture compte **6 bits**."}]$ex$::jsonb),
  ('53b26f6c-f960-5e34-adc7-f3714b4fff47'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Un mot, plusieurs lectures","competence":"analyser-document","situation":"Le logiciel de Malik reçoit le mot 01000001 sans aucune indication. Il doit aussi combiner deux mots de 4 bits, A et B, avec une addition et avec une opération logique.","documents":[{"id":"lectures","type":"tableau","titre":"Le mot 01000001 lu de trois façons","colonnes":["On le lit comme…","On obtient"],"lignes":[["un entier","65"],["un caractère ASCII","la lettre A"],["un pixel en niveaux de gris","une nuance de gris"]],"enteteLignes":false,"source":"Valeurs usuelles du codage ASCII"},{"id":"mots","type":"tableau","titre":"Deux mots de 4 bits","colonnes":["Mot","Bit 3","Bit 2","Bit 1","Bit 0"],"lignes":[["A",1,0,1,1],["B",0,1,1,0]],"enteteLignes":false,"source":"Mots écrits pour l’exercice"}],"questions":[{"enonce":"Touche la case qui dit ce que représente le mot lu comme un caractère ASCII.","aide":"Cherche la ligne « caractère ASCII ».","type":"zone","document":"lectures","multiple":false},{"enonce":"Qu’est-ce qui décide qu’un même mot de 8 bits est lu comme un entier plutôt que comme une lettre ?","aide":"Regarde ce que contient le mot : y a-t-il une indication sur sa nature ?","type":"choix","options":[{"id":"a","texte":"La valeur du premier bit en partant de la gauche"},{"id":"b","texte":"Le nombre de 1 présents dans le mot"},{"id":"c","texte":"La longueur du fichier qui contient le mot"},{"id":"d","texte":"La convention du programme qui l’interprète"}],"multiple":false},{"enonce":"On additionne A et B comme des entiers. Quel est le résultat en décimal ?","aide":"Convertis d’abord A et B en décimal avec les poids 8, 4, 2, 1.","type":"nombre"},{"enonce":"Combien de bits faut-il au minimum pour écrire cette somme en binaire ?","aide":"Avec 4 bits on va jusqu’à 15 seulement.","type":"nombre"},{"enonce":"Que donne l’opération logique A ET B, bit à bit (sans retenue) ?","aide":"Pour chaque colonne, le résultat vaut 1 seulement si les DEUX bits valent 1.","type":"choix","options":[{"id":"a","texte":"0010"},{"id":"b","texte":"1111"},{"id":"c","texte":"1101"},{"id":"d","texte":"0100"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c1"]},"explication":"Lu comme caractère ASCII, 01000001 est **la lettre A**."},{"cle":{"type":"choix","ids":["d"]},"explication":"Rien dans le mot ne dit ce qu’il représente : c’est la **convention du programme** qui l’interprète."},{"cle":{"type":"nombre","valeur":17,"tolerance":0},"affichage":"17","explication":"A = 8 + 2 + 1 = 11 et B = 4 + 2 = 6. 11 + 6 = **17**."},{"cle":{"type":"nombre","valeur":5,"tolerance":0},"affichage":"5","explication":"17 dépasse 15, le maximum sur 4 bits. 17 = 10001 en binaire : il faut **5 bits** (la somme a produit une retenue)."},{"cle":{"type":"choix","ids":["a"]},"explication":"Colonne par colonne : 1 ET 0 = 0, 0 ET 1 = 0, 1 ET 1 = 1, 1 ET 0 = 0. Résultat **0010**."}]$ex$::jsonb),
