   $ex$[{"cle":{"type":"zone","ids":["r0c3"]},"explication":"Un kibioctet vaut **1 024 octets** (2¹⁰), alors qu’un kilooctet vaut 1 000 octets."},{"cle":{"type":"nombre","valeur":3072,"tolerance":0},"affichage":"3072","explication":"3 × 1 024 = **3 072 octets**."},{"cle":{"type":"zone","ids":["z1"]},"explication":"Le « b » minuscule de Mb/s désigne le **bit** : le débit est annoncé en mégabits par seconde."},{"cle":{"type":"nombre","valeur":50,"tolerance":0},"affichage":"50 Mo/s","explication":"400 ÷ 8 = **50 Mo/s** : un débit en Mb/s est huit fois plus grand que le même débit en Mo/s."}]$ex$::jsonb),
