   $ex${"titre":"Le jeu qui charge","competence":"analyser-document","situation":"Léo lance un jeu vidéo : le jeu est copié du SSD vers la mémoire vive avant de s’exécuter, puis le processeur travaille avec ses registres et son cache. Il veut comprendre pourquoi toutes ces mémoires coexistent.","documents":[{"id":"memoires","type":"tableau","titre":"Les mémoires d’un ordinateur","colonnes":["Mémoire","Temps d’accès","Capacité typique","Efface à l’arrêt ?"],"lignes":[["SSD","100 000 ns","1 To","non"],["Registres","0,3 ns","quelques mots","oui"],["Mémoire vive","100 ns","16 Go","oui"],["Cache","2 ns","quelques Mo","oui"]],"enteteLignes":false,"source":"Ordres de grandeur arrondis"},{"id":"note","type":"texte","genre":"article","titre":"Le carnet de Léo","auteur":"Texte écrit pour l’exercice","blocs":["J’appuie sur « Jouer » : le jeu est d’abord copié du SSD dans la mémoire vive, puis le processeur en charge des morceaux dans son cache.","Quand j’éteins l’ordinateur, la mémoire vive se vide, mais mes parties sauvegardées sur le SSD sont toujours là."]}],"questions":[{"enonce":"Range ces mémoires de la plus rapide à la plus lente.","aide":"Compare les temps d’accès : plus il est petit, plus la mémoire est rapide.","type":"ordre","items":[{"id":"a","texte":"Cache"},{"id":"b","texte":"SSD"},{"id":"c","texte":"Mémoire vive"},{"id":"d","texte":"Registres"}]},{"enonce":"Combien de fois la mémoire vive est-elle plus rapide que le SSD ?","aide":"Divise le temps d’accès du SSD par celui de la mémoire vive.","type":"nombre"},{"enonce":"Trie ces mémoires selon qu’elles gardent ou non leur contenu quand la machine est éteinte.","aide":"Regarde la dernière colonne du tableau et le carnet de Léo.","type":"categories","categories":[{"id":"c0","texte":"Volatile"},{"id":"c1","texte":"Persistante"}],"items":[{"id":"i0","texte":"Cache"},{"id":"i1","texte":"Mémoire vive"},{"id":"i2","texte":"Disque dur"},{"id":"i3","texte":"Registres"},{"id":"i4","texte":"SSD"}]},{"enonce":"Pourquoi ne met-on pas tout le jeu directement dans les registres, les plus rapides ?","aide":"Regarde la colonne des capacités.","type":"choix","options":[{"id":"a","texte":"Le processeur n’a pas le droit de lire dans ses propres registres"},{"id":"b","texte":"Plus une mémoire est rapide, plus elle coûte cher et plus elle est petite"},{"id":"c","texte":"Les registres sont persistants et ne peuvent plus être effacés une fois écrits"},{"id":"d","texte":"Les registres ne savent mémoriser que des lettres et jamais des nombres"}],"multiple":false}]}$ex$::jsonb,
