   $ex${"titre":"Le processeur qui guette le clavier","competence":"raisonner","situation":"Un processeur doit détecter les frappes sur un clavier. Dans un premier système, il va regarder lui-même si une touche est enfoncée, toutes les 10 ms. Dans un second, c’est le clavier qui le prévient.","documents":[{"id":"frappes","type":"tableau","titre":"Les trois frappes de Yanis","colonnes":["Frappe","Instant d’arrivée (ms)"],"lignes":[["Touche A",12],["Touche B",25],["Touche C",31]],"enteteLignes":false,"source":"Chronologie inventée pour l’exercice"},{"id":"systeme","type":"texte","genre":"article","titre":"Le système de scrutation","auteur":"Texte écrit pour l’exercice","blocs":["Le processeur vérifie le clavier aux instants 0, 10, 20, 30, 40 ms…","Chaque vérification lui coûte 5 µs de calcul, qu’une touche ait été frappée ou non. Une frappe n’est prise en compte qu’à la vérification suivante."]}],"questions":[{"enonce":"Combien de temps la frappe B attend-elle avant d’être détectée par scrutation ?","aide":"Prochaine vérification après 25 ms ?","type":"nombre","unite":"ms"},{"enonce":"Quelle est l’attente totale des trois frappes A, B et C ?","aide":"A arrive à 12 (vérifiée à 20), C arrive à 31 (vérifiée à 40).","type":"nombre","unite":"ms"},{"enonce":"Combien de vérifications le processeur fait-il en une seconde, à raison d’une toutes les 10 ms ?","aide":"1 s = 1 000 ms.","type":"nombre"},{"enonce":"Combien de microsecondes de calcul par seconde sont consommées par ces vérifications, même si personne ne tape ?","aide":"100 vérifications de 5 µs.","type":"nombre","unite":"µs"},{"enonce":"Dans le second système, quand le processeur apprend-il qu’une touche est frappée ?","aide":"Le périphérique demande l’attention du processeur.","type":"choix","options":[{"id":"a","texte":"Quand la mémoire vive est pleine"},{"id":"b","texte":"Seulement quand l’utilisateur relâche la touche"},{"id":"c","texte":"À la prochaine vérification qu’il décide de faire"},{"id":"d","texte":"Tout de suite : le clavier envoie une interruption"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":5,"tolerance":0},"affichage":"5 ms","explication":"B arrive à 25 ms ; la prochaine vérification est à 30 ms : attente de **5 ms**."},{"cle":{"type":"nombre","valeur":22,"tolerance":0},"affichage":"22 ms","explication":"A : 20 − 12 = 8 ms ; B : 5 ms ; C : 40 − 31 = 9 ms. Total **22 ms**."},{"cle":{"type":"nombre","valeur":100,"tolerance":0},"affichage":"100","explication":"1 000 ms ÷ 10 ms = **100 vérifications** par seconde."},{"cle":{"type":"nombre","valeur":500,"tolerance":0},"affichage":"500 µs","explication":"100 × 5 µs = **500 µs** par seconde, dépensées pour rien quand aucune touche n’est frappée."},{"cle":{"type":"choix","ids":["d"]},"explication":"Avec une **interruption**, le périphérique prévient lui-même le processeur : plus d’attente ni de vérifications inutiles."}]$ex$::jsonb),
