   $ex${"titre":"TCP, UDP et le téléchargement lent","competence":"analyser-document","situation":"Une plateforme choisit son protocole selon le service et cherche pourquoi un envoi message par message est lent. Maël compare les besoins de cinq applications, puis le débit du bit alterné et d’une fenêtre TCP.","documents":[{"id":"applis","type":"tableau","titre":"Les besoins de cinq applications","colonnes":["Application","Besoin principal"],"lignes":[["Téléchargement d’un fichier","Chaque octet doit arriver, dans l’ordre"],["Appel vidéo en direct","Un paquet en retard est inutile"],["Chargement d’une page web","Contenu complet et dans l’ordre"],["Envoi d’un courriel","Aucune perte n’est admise"],["Conversation vocale","Un paquet retransmis arriverait trop tard"]],"enteteLignes":false,"source":"Tableau écrit pour l’exercice"},{"id":"debits","type":"tableau","titre":"Messages en vol sur un même lien","colonnes":["Protocole","Messages en vol","Taille d’un message","Aller-retour"],"lignes":[["Bit alterné",1,"1 000 octets","100 ms"],["TCP, fenêtre de 10",10,"1 000 octets","100 ms"]],"enteteLignes":false,"source":"Valeurs choisies pour l’exercice"}],"questions":[{"enonce":"Choisis le protocole adapté à chaque application.","aide":"Pour la voix et la vidéo en direct, un paquet retransmis arrive trop tard pour être joué.","type":"categories","categories":[{"id":"c0","texte":"TCP"},{"id":"c1","texte":"UDP"}],"items":[{"id":"i0","texte":"Envoi d’un courriel"},{"id":"i1","texte":"Appel vidéo en direct"},{"id":"i2","texte":"Conversation vocale"},{"id":"i3","texte":"Chargement d’une page web"},{"id":"i4","texte":"Téléchargement d’un fichier"}]},{"enonce":"Avec le bit alterné, un seul message de 1 000 octets circule par aller-retour de 100 ms. Quel est le débit utile, en octets par seconde ?","aide":"Combien d’allers-retours en une seconde ?","type":"nombre","unite":"octets/s"},{"enonce":"Avec une fenêtre de 10 messages en vol, quel est le débit utile, en octets par seconde ?","aide":"Même calcul, mais 10 messages par aller-retour.","type":"nombre","unite":"octets/s"},{"enonce":"Pourquoi la fenêtre TCP accélère-t-elle le transfert, par rapport au bit alterné ?","aide":"Compare la colonne « Messages en vol » des deux lignes.","type":"choix","options":[{"id":"a","texte":"Elle supprime les accusés de réception, qui ralentissent tout"},{"id":"b","texte":"Elle remplace l’adresse IP par une adresse plus courte"},{"id":"c","texte":"Elle permet de ne plus jamais retransmettre un message perdu"},{"id":"d","texte":"Plusieurs messages sont en vol en même temps"}],"multiple":false},{"enonce":"Pourquoi n’utilise-t-on pas UDP pour télécharger un fichier ?","aide":"Chaque octet du fichier doit arriver, dans l’ordre.","type":"choix","options":[{"id":"a","texte":"UDP ne sait pas envoyer plus de dix octets"},{"id":"b","texte":"UDP exige un compte chez le fournisseur d’accès"},{"id":"c","texte":"UDP ne garantit ni l’arrivée, ni l’ordre des paquets"},{"id":"d","texte":"UDP est plus lent que TCP sur tous les réseaux"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c1","i3":"c0","i4":"c0"}},"explication":"**TCP** pour ce qui ne tolère aucune perte (fichier, page web, courriel) ; **UDP** pour la voix et la vidéo en direct, où le retard est pire que la perte."},{"cle":{"type":"nombre","valeur":10000,"tolerance":0},"affichage":"10 000 octets/s","explication":"10 allers-retours par seconde × 1 000 octets = **10 000 octets/s**."},{"cle":{"type":"nombre","valeur":100000,"tolerance":0},"affichage":"100 000 octets/s","explication":"10 allers-retours × 10 messages × 1 000 octets = **100 000 octets/s**."},{"cle":{"type":"choix","ids":["d"]},"explication":"Des numéros de séquence **longs** permettent plusieurs messages en vol : le canal n’attend plus chaque accusé avant d’envoyer la suite."},{"cle":{"type":"choix","ids":["c"]},"explication":"UDP n’offre **aucune garantie** : un fichier téléchargé exige que chaque octet arrive, dans l’ordre, donc TCP."}]$ex$::jsonb),
