   $ex${"titre":"La moyenne qui refuse la liste vide","competence":"analyser-document","situation":"Inès écrit la fonction qui calcule la moyenne des notes de son club. Elle la documente avec une docstring, ajoute une assertion pour se protéger, puis la teste sur trois appels.","documents":[{"id":"prog","type":"texte","genre":"consigne","titre":"La fonction documentée","auteur":"Programme écrit pour l’exercice","blocs":["def moyenne(notes):","    \"\"\"Rend la moyenne des notes.","    Précondition : la liste n’est pas vide.\"\"\"","    assert len(notes) > 0","    return sum(notes) / len(notes)"]},{"id":"tests","type":"tableau","titre":"Trois appels de test","colonnes":["Appel","Résultat"],"lignes":[["moyenne([12, 8])","?"],["moyenne([15])",15],["moyenne([])","?"]],"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Quel est le résultat de moyenne([12, 8]) ?","aide":"Additionne les notes, puis divise par leur nombre.","type":"nombre"},{"enonce":"Touche l’appel qui va déclencher l’assertion.","aide":"L’assertion vérifie que la liste n’est pas vide.","type":"zone","document":"tests","multiple":false},{"enonce":"Touche le mot qui arrête le programme quand la précondition n’est pas respectée.","aide":"Il est au début de la ligne qui suit la docstring.","type":"zone","document":"prog","multiple":false},{"enonce":"Quel serait le résultat de moyenne([14, 9, 7, 6]) ?","aide":"La somme est 36.","type":"nombre"},{"enonce":"Associe chaque mot à ce qu’il désigne.","aide":"Précondition : avant ; postcondition : après.","type":"association","gauche":[{"id":"g0","texte":"Précondition"},{"id":"g1","texte":"Postcondition"},{"id":"g2","texte":"Docstring"},{"id":"g3","texte":"Assertion"}],"droite":[{"id":"d0","texte":"Ce qui est garanti en sortie"},{"id":"d1","texte":"La chaîne placée juste sous la ligne de définition"},{"id":"d2","texte":"Une vérification qui arrête le programme si elle est fausse"},{"id":"d3","texte":"Ce que la fonction exige de ses entrées"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":10,"tolerance":0},"affichage":"10","explication":"sum vaut 20, len vaut 2 : 20 / 2 = **10**."},{"cle":{"type":"zone","ids":["r2c0"]},"explication":"Avec moyenne([]), len(notes) vaut 0 : la condition **len(notes) > 0** est fausse et le programme s’arrête là."},{"cle":{"type":"zone","ids":["m15"]},"explication":"Le mot **assert** vérifie la précondition et arrête le programme au bon endroit si elle est fausse."},{"cle":{"type":"nombre","valeur":9,"tolerance":0},"affichage":"9","explication":"14 + 9 + 7 + 6 = 36, divisé par 4 : **9**."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g3":"d2","g0":"d3"}},"explication":"La **précondition** porte sur les entrées, la **postcondition** sur ce qui est garanti en sortie, la **docstring** contient la spécification et l’**assertion** la vérifie à l’exécution."}]$ex$::jsonb),
