   $ex${"titre":"Remplir la salle de la MJC","competence":"analyser-document","situation":"Une seule salle, six demandes d’activités dans la journée. Marcus veut en caser le plus possible sans qu’elles se chevauchent ; une activité peut commencer à l’heure où la précédente finit.","documents":[{"id":"acts","type":"tableau","titre":"Les demandes de la journée","colonnes":["Activité","Début (h)","Fin (h)"],"lignes":[["A",8,16],["B",9,10],["C",10,12],["D",11,13],["E",12,14],["F",14,15]],"source":"Horaires écrits pour l’exercice"},{"id":"schema","type":"chaine","titre":"La méthode gloutonne","disposition":"colonne","noeuds":[{"id":"z1","texte":"Trier les activités par heure de fin"},{"id":"z2","texte":"Prendre la première activité compatible"},{"id":"z3","texte":"L’ajouter définitivement"},{"id":"z4","texte":"Recommencer jusqu’à épuisement"}],"liens":[{"de":"z1","a":"z2"},{"de":"z2","a":"z3"},{"de":"z3","a":"z4"}],"source":"D’après le cours de NSI"}],"questions":[{"enonce":"Range les activités par heure de fin croissante.","aide":"Compare uniquement la colonne « Fin ».","type":"ordre","items":[{"id":"a","texte":"B : de 9 h à 10 h"},{"id":"b","texte":"A : de 8 h à 16 h"},{"id":"c","texte":"C : de 10 h à 12 h"},{"id":"d","texte":"E : de 12 h à 14 h"},{"id":"e","texte":"D : de 11 h à 13 h"},{"id":"f","texte":"F : de 14 h à 15 h"}]},{"enonce":"Touche les activités retenues par la méthode gloutonne.","aide":"On garde B, puis la première activité qui commence à 10 h ou après, et ainsi de suite.","type":"zone","document":"acts","multiple":true},{"enonce":"Combien d’activités la méthode gloutonne retient-elle ?","aide":"Compte les activités touchées à la question précédente.","type":"nombre"},{"enonce":"Marcus préfère prendre d’abord l’activité qui commence le plus tôt. Combien d’activités retient-il alors ?","aide":"Celle qui commence à 8 h finit à 16 h.","type":"nombre"},{"enonce":"Pourquoi « finir le plus tôt » est-il le bon critère ?","aide":"Pense à ce qui reste de la journée après chaque choix.","type":"choix","options":[{"id":"a","texte":"Il laisse le plus de temps libre pour les activités suivantes"},{"id":"b","texte":"Il garantit que chaque activité sera retenue"},{"id":"c","texte":"Il évite de trier les demandes"},{"id":"d","texte":"Il retient toujours les activités les plus courtes"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"ordre","ids":["a","c","e","d","f","b"]},"explication":"Les fins sont 10, 12, 13, 14, 15 puis 16 : **B, C, D, E, F, A**."},{"cle":{"type":"zone","ids":["r1c0","r2c0","r4c0","r5c0"]},"explication":"On retient **B** (fin 10 h), **C** (10 h – 12 h), puis **E** (12 h – 14 h) et **F** (14 h – 15 h) ; D chevauche C, A chevauche tout."},{"cle":{"type":"nombre","valeur":4,"tolerance":0},"affichage":"4","explication":"B, C, E et F : **4** activités."},{"cle":{"type":"nombre","valeur":1,"tolerance":0},"affichage":"1","explication":"L’activité A occupe toute la journée : elle empêche toutes les autres, soit **1** activité. Ce critère est mauvais."},{"cle":{"type":"choix","ids":["a"]},"explication":"Choisir l’activité qui finit le plus tôt libère le plus de temps pour la suite : ce critère est **prouvé optimal** pour le choix d’activités."}]$ex$::jsonb),
  ('ace13ca2-a686-5405-b180-aa595b2f44b8'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Trois projets pour une IA","competence":"analyser-document","situation":"Un club de NSI imagine trois projets d’apprentissage automatique. Pour chacun, il liste les données dont il dispose.","documents":[{"id":"projets","type":"tableau","titre":"Trois projets","colonnes":["Projet","Données disponibles"],"lignes":[["Classer des courriels","5 000 courriels déjà marqués « indésirable » ou « normal »"],["Prévoir le prix d’un logement","3 000 ventes passées avec leur prix"],["Regrouper des clients","Des historiques d’achats, sans aucune catégorie"]],"source":"Projets écrits pour l’exercice"}],"questions":[{"enonce":"Touche le projet dont les données n’ont pas d’étiquette.","aide":"Une étiquette est la réponse attendue, déjà connue pour chaque exemple.","type":"zone","document":"projets","multiple":false},{"enonce":"Associe chaque projet à sa tâche.","aide":"Un prix est un nombre ; une catégorie est un choix parmi quelques-unes.","type":"association","gauche":[{"id":"g0","texte":"Classer des courriels"},{"id":"g1","texte":"Prévoir le prix d’un logement"},{"id":"g2","texte":"Regrouper des clients"}],"droite":[{"id":"d0","texte":"Régression"},{"id":"d1","texte":"Classification"},{"id":"d2","texte":"Partitionnement"}]},{"enonce":"Qu’est-ce qui caractérise l’apprentissage supervisé ?","aide":"Pense aux courriels déjà marqués.","type":"choix","options":[{"id":"a","texte":"Il n’utilise aucune donnée"},{"id":"b","texte":"Il part d’exemples étiquetés"},{"id":"c","texte":"Il ne sert qu’à regrouper des données"},{"id":"d","texte":"Il applique des règles écrites à la main"}],"multiple":false}]}$ex$::jsonb,
