  ('63725c90-87aa-5c8f-958a-7aff761769a6'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"L’autonomie de la batterie de la caravane","competence":"calculer","situation":"Dans leur caravane, Hugo et Maëlle alimentent leurs appareils avec une batterie de service. Ils veulent savoir combien de jours elle tient sans recharge.","documents":[{"id":"appareils","type":"tableau","titre":"Consommation quotidienne","colonnes":["Appareil","Puissance (W)","Durée par jour (h)"],"lignes":[["Éclairage LED","12","5"],["Pompe à eau","30","2"],["Réfrigérateur","45","8"],["Chargeurs","10","4"]],"enteteLignes":true,"source":"Valeurs écrites pour l’exercice"},{"id":"batterie","type":"fiche","modele":"etiquette","entete":"Batterie de service","sousTitre":"Plaque signalétique","emoji":"🔋","lignes":[{"texte":"Tension nominale","valeur":"12 V"},{"texte":"Capacité","valeur":"100 Ah"},{"texte":"Masse","valeur":"11 kg"}],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche l’appareil qui consomme le plus d’énergie par jour.","aide":"Énergie = puissance × durée : calcule-la pour chaque appareil.","type":"zone","document":"appareils","multiple":false},{"enonce":"Calcule l’énergie totale consommée par jour, en wattheures.","aide":"Additionne les produits P × Δt de chaque ligne.","type":"nombre","unite":"Wh"},{"enonce":"La batterie stocke U × C wattheures (tension en volts × capacité en ampères-heures). Calcule cette énergie en Wh.","aide":"Lis la tension et la capacité sur la plaque signalétique.","type":"nombre","unite":"Wh"},{"enonce":"Calcule l’autonomie en jours, arrondie au dixième.","aide":"Autonomie = énergie stockée / énergie consommée par jour.","type":"nombre","unite":"jours"},{"enonce":"Exprime la consommation quotidienne en mégajoules (1 Wh = 3 600 J), arrondie au centième.","aide":"Multiplie 520 par 3 600, puis divise par 10⁶.","type":"nombre","unite":"MJ"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r2c0"]},"explication":"Éclairage 60 Wh, pompe 60 Wh, réfrigérateur 360 Wh, chargeurs 40 Wh : c’est le **réfrigérateur**."},{"cle":{"type":"nombre","valeur":520,"tolerance":0.5},"affichage":"520 Wh","explication":"12 × 5 + 30 × 2 + 45 × 8 + 10 × 4 = 60 + 60 + 360 + 40 = **520 Wh**."},{"cle":{"type":"nombre","valeur":1200,"tolerance":1},"affichage":"1200 Wh","explication":"12 V × 100 Ah = **1 200 Wh**, soit 1,2 kWh."},{"cle":{"type":"nombre","valeur":2.3,"tolerance":0.05},"affichage":"2,3 jours","explication":"1 200 / 520 ≈ **2,3 jours**."},{"cle":{"type":"nombre","valeur":1.87,"tolerance":0.01},"affichage":"1,87 MJ","explication":"520 × 3 600 = 1 872 000 J ≈ **1,87 MJ**."}]$ex$::jsonb),
  ('63725c90-87aa-5c8f-958a-7aff761769a6'::uuid, 3, 3, 15, 50, 6,
   $ex${"titre":"Remplacer le moteur de la pompe ?","competence":"modeliser","situation":"Une exploitation agricole compare deux moteurs de pompe qui fournissent la même puissance utile. L’ancien est-il à remplacer ? Le moteur fonctionne 6 h par jour, 250 jours par an ; l’électricité coûte 0,25 € le kWh ; le moteur neuf coûte 240 €.","documents":[{"id":"moteurs","type":"graphique","forme":"barres","titre":"Bilan de puissance des deux moteurs","categories":["Ancien","Neuf"],"series":[{"nom":"Puissance reçue (W)","valeurs":[800,600],"teinte":"violet"},{"nom":"Puissance perdue (W)","valeurs":[320,120],"teinte":"corail"}],"axeY":{"titre":"Puissance","unite":"W","min":0,"max":900,"pas":100},"axeX":{"titre":"Moteur"},"valeurs":true,"source":"Valeurs écrites pour l’exercice"}],"questions":[{"enonce":"Touche le moteur qui perd le moins de puissance en chaleur.","aide":"Compare les barres de puissance perdue.","type":"zone","document":"moteurs","multiple":false},{"enonce":"Quelle puissance utile fournissent les deux moteurs (en W) ?","aide":"Puissance utile = puissance reçue − puissance perdue.","type":"nombre","unite":"W"},{"enonce":"Calcule le rendement du moteur neuf (valeur entre 0 et 1).","aide":"η = puissance utile / puissance reçue.","type":"nombre"},{"enonce":"Quelle énergie électrique le moteur neuf économise-t-il en un an, en kWh ? (6 h × 250 jours = 1 500 h de marche)","aide":"Compare 0,8 kW × 1 500 h et 0,6 kW × 1 500 h : une des deux est la consommation de l’ancien.","type":"nombre","unite":"kWh"},{"enonce":"Quelle économie cela représente-t-il en euros par an ?","aide":"Multiplie les kWh économisés par le prix du kWh.","type":"nombre","unite":"€"},{"enonce":"En combien d’années le moteur neuf (240 €) est-il remboursé par l’économie ?","aide":"Divise le prix du moteur par l’économie annuelle.","type":"nombre","unite":"ans"}]}$ex$::jsonb,
