  ('79b096c3-0c69-542b-9fdc-6f2b8bed7397'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Le chauffage d’appoint du garage","competence":"analyser-document","situation":"Dans un garage mal ventilé, Louise allume un chauffage d’appoint au propane. Un détecteur enregistre la concentration en monoxyde de carbone (CO) dans la pièce. Elle veut comprendre ce qui se passe.","documents":[{"id":"chauffage","type":"fiche","modele":"etiquette","entete":"Chauffage d’appoint","sousTitre":"Notice","emoji":"🔥","lignes":[{"texte":"Combustible : propane C₃H₈"},{"texte":"Consommation","valeur":"0,20 kg par heure","id":"z1"},{"texte":"Pouvoir calorifique du propane","valeur":"46 MJ/kg"}],"source":"Texte écrit pour l’exercice"},{"id":"co","type":"graphique","forme":"courbe","titre":"Concentration en CO dans le garage","categories":["0","10","20","30","40","50","60"],"series":[{"nom":"CO (ppm)","valeurs":[0,5,20,45,80,120,170],"teinte":"corail"}],"axeY":{"titre":"CO","unite":"ppm","min":0,"max":200,"pas":50},"axeX":{"titre":"Temps (min)"},"valeurs":false,"source":"Valeurs écrites pour l’exercice"}],"questions":[{"enonce":"Le seuil d’alerte du détecteur est 50 ppm. Touche le premier instant où la concentration dépasse ce seuil.","aide":"Cherche le premier point au-dessus de 50.","type":"zone","document":"co","multiple":false},{"enonce":"Complète l’équation de combustion incomplète du propane.","aide":"Compte les atomes d’oxygène à droite : 6 + 8.","type":"trous","segments":["2 C₃H₈ + ",0," O₂ → 6 CO + 8 H₂O"]},{"enonce":"Calcule la puissance thermique du chauffage en kW : énergie libérée en une heure (0,20 kg × 46 MJ/kg) divisée par 3 600 s. Arrondis au dixième.","aide":"Énergie en MJ puis en J, avant de diviser par 3 600 s.","type":"nombre","unite":"kW"},{"enonce":"Le détecteur sonne. Que faut-il faire ?","aide":"Le CO prend la place du dioxygène dans le sang : il faut renouveler l’air.","type":"choix","options":[{"id":"a","texte":"Fermer les fenêtres pour garder la chaleur"},{"id":"b","texte":"Rallumer à puissance maximale pour finir"},{"id":"c","texte":"Attendre que la concentration redescende"},{"id":"d","texte":"Aérer, éteindre le chauffage et sortir"}],"multiple":false}]}$ex$::jsonb,
