   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"L’**ampèremètre** (symbole A) mesure l’intensité du courant, ici 0,040 A."},{"cle":{"type":"zone","ids":["z3"]},"explication":"Le **conducteur ohmique** de 150 Ω est le récepteur : il reçoit l’énergie et la transforme en chaleur (effet Joule)."},{"cle":{"type":"nombre","valeur":6,"tolerance":0.01},"affichage":"6 V","explication":"U = 150 × 0,040 = **6,0 V** : on retrouve la tension du générateur, car il n’y a qu’un seul récepteur."},{"cle":{"type":"nombre","valeur":0.24,"tolerance":0.005},"affichage":"0,24 W","explication":"P = 6,0 × 0,040 = **0,24 W**. (On trouve la même chose avec P = R × I² = 150 × 0,040².)"}]$ex$::jsonb),
