   $ex${"titre":"La prise de courant à l’oscilloscope","competence":"lire-graphique","situation":"Au lycée, Nora observe à l’oscilloscope la tension du secteur français. Elle compare ensuite avec des relevés faits sur des prises étrangères.","documents":[{"id":"secteur","type":"graphique","forme":"courbe","titre":"Tension du secteur sur une période","categories":["0","2,5","5","7,5","10","12,5","15","17,5","20"],"series":[{"nom":"u (V)","valeurs":[0,230,325,230,0,-230,-325,-230,0],"teinte":"violet"}],"axeY":{"titre":"u","unite":"V","min":-400,"max":400,"pas":100},"axeX":{"titre":"Temps (ms)"},"valeurs":false,"source":"Valeurs arrondies, écrites pour l’exercice"},{"id":"etranger","type":"tableau","titre":"Relevés sur deux prises étrangères","colonnes":["Pays","Tension maximale (V)"],"lignes":[["Japon","141"],["États-Unis","170"]],"enteteLignes":true,"source":"Valeurs arrondies"}],"questions":[{"enonce":"Touche l’instant où la tension est maximale.","aide":"Cherche le sommet de la courbe.","type":"zone","document":"secteur","multiple":false},{"enonce":"Lis la période T de la tension sur le graphique, en ms.","aide":"Combien de temps faut-il pour retrouver la même valeur en repartant dans le même sens ?","type":"nombre","unite":"ms"},{"enonce":"Calcule la fréquence f = 1 / T, en hertz.","aide":"Convertis T = 20 ms en secondes : 0,020 s.","type":"nombre","unite":"Hz"},{"enonce":"Calcule la valeur efficace de la tension (U eff = U max / √2), arrondie à l’unité.","aide":"Lis U max sur le graphique, puis divise par √2 ≈ 1,414.","type":"nombre","unite":"V"},{"enonce":"Quelle est la valeur moyenne de cette tension sur une période ?","aide":"Observe l’aire au-dessus et en dessous de l’axe.","type":"choix","options":[{"id":"a","texte":"0 V"},{"id":"b","texte":"230 V"},{"id":"c","texte":"325 V"},{"id":"d","texte":"162 V"}],"multiple":false},{"enonce":"Calcule la valeur efficace de la tension aux États-Unis à l’aide du tableau, arrondie à l’unité.","aide":"Utilise la tension maximale de la ligne États-Unis.","type":"nombre","unite":"V"}]}$ex$::jsonb,
